{"cards": [{"node_code": "N_1cae9e6f4a41703b", "definition": "研究车辆停放与存储设施（如停车场、停车库）的规划、设计、布局及运营管理，涵盖停车需求预测、周转率分析及停车诱导系统。", "boundary": "本节点聚焦于“静态”车辆存储与停放空间。边界在于区分“动态”交通流（归入交通系统或交通管制）与“静态”停放。若内容涉及停车场的土建结构施工，归入道路工程或土木工程；若涉及停车收费的经济定价策略，可关联运输经济，但设施设计归本节点。", "includes": ["停车场与停车库的选址、规模确定及平面布置", "停车需求预测模型、周转率分析及停车诱导技术", "停车设施的交通组织、出入口设计及安全管理"], "excludes": ["停车场土建结构设计与施工（归入道路工程或土木工程）", "纯停车收费价格制定与财务分析（归入运输经济）"], "sibling_distinctions": [{"other_code": "N_f382063d5965c7d4", "rule": "车辆停厝侧重车辆存储与停放空间；路侧服务设施侧重为行驶中或短暂停留车辆提供加油、维修、餐饮等辅助服务。"}, {"other_code": "N_d4f84a94441d5fb3", "rule": "交通管制侧重动态交通流的信号与规则管理；车辆停厝侧重静态停车空间的规划与管理。"}], "cross_boundary_rule": "若内容涉及“智慧停车”，侧重停车空间管理与诱导归本节点；若侧重停车数据背后的城市交通规划决策，可关联交通调查与规划。"}, {"node_code": "N_f382063d5965c7d4", "definition": "研究公路沿线为车辆及人员提供辅助服务的设施，包括加油站、加气站、维修站、服务区、休息区及路侧停车带的设计与管理。", "boundary": "本节点聚焦于“服务”功能，即支持车辆运行和人员休息的辅助设施。边界在于区分“交通设施”（如信号灯、标志，归入交通安全设施）与“服务设施”。若内容涉及服务区内的土建建筑结构设计，归入土木工程；若涉及服务区商业运营的经济分析，归入运输经济。", "includes": ["公路服务区、停车区、加油加气站的选址与布局", "车辆维修、救援、充电等路侧服务设施的技术标准", "路侧服务设施的交通组织、安全设计及环境处理"], "excludes": ["交通信号、标志标线等交通安全设施（归入线路交通安全设施）", "服务区内部商业经营策略与财务分析（归入运输经济）"], "sibling_distinctions": [{"other_code": "N_1cae9e6f4a41703b", "rule": "路侧服务设施侧重行驶途中的辅助服务（加油、休息、维修）；车辆停厝侧重车辆存储与停放空间。"}, {"other_code": "N_437eae7c53f019bb", "rule": "线路交通安全设施侧重保障通行安全（护栏、标志）；路侧服务设施侧重提供运行辅助服务（加油、餐饮）。"}], "cross_boundary_rule": "若内容涉及“综合服务区”，侧重交通组织与安全设计归本节点；若侧重服务区建筑结构设计，可关联土木工程。"}, {"node_code": "N_2db12ba0f600add3", "definition": "研究交通活动产生的负面外部性，包括噪声、废气排放、振动及视觉污染等公害的监测、评价、预测及治理技术。", "boundary": "本节点聚焦于交通对环境的“负面影响”及治理。边界在于区分“交通安全”（归入交通事故或安全设施）与“交通公害”（环境与健康影响）。若内容涉及车辆尾气净化器内部机械结构，归入汽车工程；若涉及宏观环保政策，归入环境科学，本节点侧重交通工程视角的治理措施。", "includes": ["交通噪声、废气、振动的监测、评价标准及预测模型", "交通公害治理工程措施（如隔音屏障、绿化隔离带）", "交通对周边环境影响的评估方法及缓解策略"], "excludes": ["车辆内部尾气净化装置机械构造（归入汽车工程）", "宏观环境保护政策与法律体系（归入环境科学或公共管理）"], "sibling_distinctions": [{"other_code": "N_1ccb89c563fc8291", "rule": "交通事故侧重人身伤亡与财产损失；交通公害侧重噪声、污染等对环境和健康的长期影响。"}, {"other_code": "N_437eae7c53f019bb", "rule": "线路交通安全设施侧重防止事故发生的物理防护；交通公害侧重治理事故或运行产生的环境污染。"}], "cross_boundary_rule": "若内容涉及“绿色交通”，侧重工程治理措施归本节点；若侧重交通规划中的环境评价方法，可关联交通调查与规划。"}]}
